        if (doc.analysis.issue === 'providerOutcomeUnknown') throw conflict('ADMIN_IMPORT_ANALYSIS_OUTCOME_UNKNOWN');
        if (doc.analysis.generation >= LIMITS.generations) throw conflict('ADMIN_IMPORT_BUDGET_EXHAUSTED');
